/**
 * dsh-chat-plus — 鲸鱼娘立绘素材（base64 内联，零网络请求）。
 *
 * ⚠ 2026-10-26 起**已停用**（见 WhalePortrait.tsx 顶部说明）：卡头换成
 * SeekerStage.tsx 的 9 段任务动画，这份 base64 素材不再进产物（build 后
 * lib/client.js 里已经没有它）。留在仓库只是为了留住那份立绘原件。
 *
 * 为什么内联而不是走 host 路由：
 *  1. 右栏卡片每 250ms 重渲染一次，走 HTTP 首屏会闪一帧空白；
 *  2. 体积可控 —— 400px WebP 共 75KB，比一次网络往返更划算。
 *
 * 分层的原因只有一个：**尾巴要单独摇**。
 *  · portrait：整张立绘（尾巴位置已挖空并用邻近色补底，所以转动不露缝）
 *  · tail：尾鳍本体，绕根部旋转 ±7°
 *
 * 画布坐标系：400 × 587（与 PORTRAIT_W/H 一致）。
 * 素材来自用户提供的 1280×1881 立绘，等比缩放到 400 宽。
 */

/** 画布宽度（px）。CSS 里所有层的 left/top 都基于这个坐标系。 */
export const PORTRAIT_W = 400
/** 画布高度（px）。 */
export const PORTRAIT_H = 587

/** 整张立绘（尾巴处已挖空）。 */
export const PORTRAIT_SRC = 'data:image/webp;base64,'

/** 尾鳍层（只含尾鳍本体）。 */
export const TAIL_SRC = 'data:image/webp;base64,'

/** 尾鳍层在画布中的位置与尺寸。 */
export const TAIL_BOX = { left: 264.06, top: 368.75, width: 114, height: 130 } as const
